import{_ as l,l as o,o as e,c as i,v as r,p as s,x as n,d as p,i as u,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"互换价差","description":"","frontmatter":{"title":"互换价差","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/swap-spread.md","filePath":"quant/swap-spread.md","lastUpdated":1789023840000}'),d={name:"quant/swap-spread.md"};function S(E,a,f,B,m,c){const t=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="互换价差" tabindex="-1">互换价差 <a class="header-anchor" href="#互换价差" aria-label="Permalink to &quot;互换价差&quot;">​</a></h1><div class="epigraph"><p>互换收益率相对国债的价差，把银行信用、抵押融资、国债特殊性和期限供需同时写进同一个基点；它不是无风险利率的「纯信用」。</p><footer>—— Duffie &amp; Singleton, An Econometric Model of the Term Structure of Interest-Rate Swap Yields, Journal of Finance, 1997</footer></div><p>同一到期的平价互换利率减去国债收益率，叫做互换价差（swap spread）。危机前的美元 10Y 价差通常为正：互换浮动端带银行信用，国债带特殊性和税收优势，Duffie 与 Singleton（1997）用强度框架把可违约短端接到互换曲线。Liu、Longstaff 与 Mandell（2006）把价差拆成信用风险的市场价格与流动性。Feldhütter 与 Lando（2008）进一步分解出国债便利收益、信用与互换市场自身的因素。2008 年之后长端美元价差可以变负，Klingler 与 Sundaresan（2019）用养老金的久期需求解释「负互换价差之谜」。本篇写价差是哪几条曲线之差、多曲线时代它如何改名，以及它与<a href="/quant/basis-swap">基差互换</a>、<a href="/quant/multi-curve-ois">OIS 与多曲线</a>、<a href="/quant/sofr-transition">SOFR 过渡</a>的分工。它补的是<a href="/quant/hull-white">Hull-White</a> 与 <a href="/quant/hjm">HJM</a> 通常假定的「单一无风险曲线」缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单曲线世界里，互换利率是折现加权的远期平均，国债收益率是同一折现下带票息的内部收益率，二者之差应主要反映浮动指数相对「无风险」的信用与流动性。问题是「无风险」从未唯一：回购特殊、国债作为抵押和监管高质量流动资产的便利、以及互换边的 CSA 抵押，都会进入价差。把互换价差当成 CDS 或当成 LIBOR–OIS，会把至少三个市场挤进一个数。</p><p>危机后，折现应从抵押隔夜指数走，投影仍按合同指数走，国债还是第三张曲线。于是至少有三种「价差」：LIBOR（或期限 SOFR）互换对国债、OIS/SOFR 互换对国债、LIBOR 对 OIS。旧习惯把第一种叫 swap spread，今天若不声明指数与折现，跨期比较没有意义。<a href="/quant/key-tenor-dv01">关键期限 DV01</a> 必须把国债曲线与互换曲线分成两列，否则价差一动，久期对冲的残差会被写成「无法解释」。</p><h3 id="负价差不是公式算错" tabindex="-1">负价差不是公式算错 <a class="header-anchor" href="#负价差不是公式算错" aria-label="Permalink to &quot;负价差不是公式算错&quot;">​</a></h3><p>2010 年代美元 30Y 互换利率可以低于同期限国债。教科书「互换含银行信用故应更贵」在这里失败。监管提高了持有互换的资产负债表成本（杠杆率、G-SIB、清算保证金），同时国债因清算、再抵押与 HQLA 获得便利收益；养老金与保险人需要长久期，现券供给跟不上时，会进入收固定的互换，把互换利率压到国债之下。Klingler–Sundaresan 把资金不足的养老金计划与负长端价差连在一起。这是供需与监管，不是无套利恒等式被违反到可以无限套利：套利要占用经销商资本，资本有价格。</p><p><span class="marginnote">比较互换与国债时，票息、日计数、节假日与 CTD 都会造出一个「假价差」。应先把两者换成同一曲线坐标下的平价收益率或同一关键点的零息，再减。用 10Y on-the-run 的 YTM 直接减 10Y 互换，是报价习惯，不是干净的风险因子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>定义。</strong> 对到期 \\(T\\)，</p> \\[\\mathrm{SS}(T)=S_{\\mathrm{swap}}(T)-y_{\\mathrm{Gov}}(T), \\]<p>其中 \\(S_{\\mathrm{swap}}\\) 是指定指数、指定折现下的平价互换利率，\\(y_{\\mathrm{Gov}}\\) 是同期限政府债的平价收益率（或对应零息）。符号惯例随市场：正价差表示互换利率更高。报告应同时给出 OIS–Treasury 与 IBOR–OIS，避免只留一个残差。</p><p><strong>分解。</strong> Feldhütter–Lando 一类的状态空间把价差写成便利收益、强度信用、流动性与测量误差。交易台的工程分解更粗、但必须可对冲：</p><ul><li>国债腿：用国债期货或现券的关键期限 DV01 对冲政府曲线；</li><li>互换腿：用同指数互换对冲；</li><li>剩余：swap spread DV01，用价差本身或「收国债、付互换」的盒式组合对冲。</li></ul><p>Johannes 与 Sundaresan（2007）强调抵押对互换利率的影响：有 CSA 的互换更靠近 OIS 折现，无抵押互换还要加 CVA/FVA，不能与国债比同一个价差。多曲线构建见 Bianchetti（2010）与本站<a href="/quant/multi-curve-ois">多曲线</a>：先自助折现，再自助投影，国债曲线单独存在。</p><p><strong>交易。</strong> 收价差（收互换固定、空头国债）押价差收窄；方向相反则押走阔。仓位对水平和斜率的泄漏要用<a href="/quant/curve-butterfly">曲线蝶式</a>那套正交化处理，否则宏观降息会被当成价差技能。长端负价差交易还暴露监管日历与发行窗口，不是平稳的均值回复。</p><h3 id="从-libor-价差到-sofr-价差" tabindex="-1">从 LIBOR 价差到 SOFR 价差 <a class="header-anchor" href="#从-libor-价差到-sofr-价差" aria-label="Permalink to &quot;从 LIBOR 价差到 SOFR 价差&quot;">​</a></h3><p>LIBOR 停用后，美元标准互换转到 SOFR。SOFR 是担保隔夜回购，几乎不含银行无担保信用，SOFR 互换对国债的价差更接近「抵押利率对国债便利」加上期限溢价与供需，而不是 Duffie–Singleton 原文里的银行强度。旧的 LIBOR swap spread 时间序列不能改名后接着做统计。残余 LIBOR 合同的后备利差是历史中位数，与当前 SOFR–Treasury 不是同一个对象，见<a href="/quant/sofr-transition">SOFR 过渡</a>。跨币种还有<a href="/quant/xccy-basis">交叉货币基差</a>，不要把 EUR swap spread 与 EURUSD basis 加总成「欧洲信用」。</p><p>一因子 <a href="/quant/hull-white">Hull-White</a> 若只拟合一条曲线，互换与国债被当成同一 \\(r\\) 的不同票息，价差被锁死为负的凸性差异，量级远小于市场。要把价差当成因子，至少两条曲线、或在 HJM/LMM 里给政府与互换不同的折现与投影。风险中性定价可以取今朝价差曲线为初值，但不解释它为何是这个形状。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>互换把浮动信用指数与固定端交换；国债把主权信用与税收、回购便利绑在一起。价差上升，可能是银行信用恶化（LIBOR 时代）、可能是国债更特殊（on-the-run、挤兑式避险）、也可能是互换固定端被久期需求压低失败、供给反而涌入。同一方向的基点，对冲工具完全不同：信用用 CDS 或 LIBOR–OIS，特殊性用 repo 与 on/off-the-run，久期供需用长端互换对超长国债。把价差当单一信用利差，是 2008 年前教材最常见的简化，也是 2016 年后 PnL 解释最常见的失败。</p><p>便利收益使国债收益率可以系统性低于抵押利率：你为了持有可质押、可交割、可满足 LCR 的券，愿意接受更低的收益。互换没有这张「券」，只有对对手方或 CCP 的风险敞口与保证金。于是 OIS/SOFR 对国债仍可保持正或负的期限结构，取决于谁更缺可质押的久期。这与结构信用模型里的<a href="/quant/merton-structural">Merton</a> 利差不是同一微观：主权违约强度几乎不解释美元 10Y 互换价差的日波动。</p><h3 id="价差的关键期限结构" tabindex="-1">价差的关键期限结构 <a class="header-anchor" href="#价差的关键期限结构" aria-label="Permalink to &quot;价差的关键期限结构&quot;">​</a></h3><p>短端价差更受政策走廊、准备金与回购设施影响；中段受抵押贷款对冲与公司发行；长端受养老金、保险与国债超长供给。因此价差本身也有水平、斜率、曲率，可以用关键期限价差 DV01 来管，而不是一个 10Y 数打天下。负 30Y 与正 2Y 可以同时出现，平行的「价差久期」会把符号对冲掉，留下扭曲。这与政府曲线的三因子平行，只是现在因子定义在两条曲线的差上。</p><p><span class="marginnote">用 CDS 解释 LIBOR 互换价差，在银行 CDS 流动性好的年份有帮助；用同一套回归解释 SOFR 互换价差，系数应当塌缩——担保隔夜不应该再按无担保银行强度定价。回归样本跨过 2023 年停用而不分段，是在估计一个不存在的结构。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在单曲线 Hull–White 树里「校准互换价差」却仍用同一 \\(P(0,T)\\) 折现国债复制组合。不要把 swap spread 的历史均值当锚：制度断点（清算强制、LIBOR 停用、QT/QE）会移动无条件均值。不要忽略期货 CTD：用国债期货对冲互换，价差 PnL 里含 cheapest 切换。税务（某些市场的国债利息税收优势）会造出无法用信用对冲的结构性价差。</p><p>模型选择：相对价值研究用统计分解（Feldhütter–Lando 类）；交易记账用两条可交易曲线的关键 01；衍生品定价用多曲线加价差曲面的缓慢因子。三者不要混成一个「信用调整的 \\(r\\)」。对冲不足时，先看泄漏到<a href="/quant/curve-butterfly">曲线蝶式</a> 和期限<a href="/quant/basis-swap">基差</a>，再问是否要上信用模型。</p><p><span class="marginnote">Duffie–Singleton（1997）的对象是互换收益率的期限结构，强度是可违约短端；它仍然有用，但今日美元标准指数已是 SOFR。引用该文时应说清：你借用的是「可违约仿射曲线」技术，还是「LIBOR 信用」故事。</span></p>',30)),(e(),s(h,null,{default:n(()=>[u(t,{id:"mermaid-100",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOV%5B%22%E5%9B%BD%E5%80%BA%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20SS%5B%22%E4%BA%92%E6%8D%A2%E4%BB%B7%E5%B7%AE%20SS(T)%22%5D%0A%20%20SW%5B%22%E4%BA%92%E6%8D%A2%E5%B9%B3%E4%BB%B7%E5%88%A9%E7%8E%87%22%5D%20--%3E%20SS%0A%20%20SS%20--%3E%20CR%5B%22%E9%93%B6%E8%A1%8C%20%2F%20%E6%8C%87%E6%95%B0%E4%BF%A1%E7%94%A8%22%5D%0A%20%20SS%20--%3E%20CONV%5B%22%E5%9B%BD%E5%80%BA%E4%BE%BF%E5%88%A9%E4%B8%8E%E7%89%B9%E6%AE%8A%E6%80%A7%22%5D%0A%20%20SS%20--%3E%20DEM%5B%22%E9%95%BF%E7%AB%AF%E4%B9%85%E6%9C%9F%E4%BE%9B%E9%9C%80%22%5D%0A%20%20SS%20--%3E%20REG%5B%22%E8%B5%84%E6%9C%AC%E4%B8%8E%E6%B8%85%E7%AE%97%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20OIS%5B%22OIS%20%2F%20SOFR%20%E6%8A%98%E7%8E%B0%22%5D%20--%3E%20SPLIT%5B%22%E6%8B%86%E6%88%90%20OIS-Treasury%20%E4%B8%8E%20IBOR-OIS%22%5D%0A%20%20SW%20--%3E%20SPLIT%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>互换价差是指定指数的平价互换利率减去同期限政府收益率，混合了信用、便利、流动性与监管供需。</li><li>Duffie–Singleton（1997）、Liu–Longstaff–Mandell（2006）、Feldhütter–Lando（2008）给出可违约曲线与分解；负长端价差见 Klingler–Sundaresan（2019）。</li><li>多曲线下必须拆开国债、OIS/SOFR 与投影指数，旧的单一 LIBOR swap spread 不能直接续用。</li><li>对冲是两条曲线的关键期限 DV01 之差，不是一个平行利差久期。</li><li>一因子短端模型锁死价差，不能当作相对价值引擎。</li><li>出处：Duffie &amp; Singleton, <em>Journal of Finance</em>, 1997；Liu, Longstaff &amp; Mandell, <em>Journal of Finance</em>, 2006；Feldhütter &amp; Lando, <em>Journal of Financial Economics</em>, 2008；Klingler &amp; Sundaresan, <em>Journal of Finance</em>, 2019；Johannes &amp; Sundaresan, <em>Journal of Finance</em>, 2007。</li></ul>',2))])}const R=l(d,[["render",S]]);export{A as __pageData,R as default};
